const headers = $json.headers || {};
const authHeader = headers.authorization || headers.Authorization || '';
let authorized = true;
if (secret && secret.length > 0) {
  authorized = authHeader === ('Bearer ' + secret);
}
return [{ json: { ...$json, authorized } }];

