  historicalProbability: {
    setupType: row.setup_type,
    target1HitPct: row.historical_target1_hit_pct,
    stopHitPct: row.historical_stop_hit_pct,
    sampleSize: row.historical_sample_size,
  },
  longTermQuality: {
    // Price-only durable-uptrend score (untuned heuristic, docs/SCORING.md)
    // plus dividend signals from the weekly import. Screening aids for a
    // long holding horizon — not forecasts, not investment advice.
    longTermScore: row.long_term_score,
    dividendTtm: row.dividend_ttm,
    dividendYieldPct: row.dividend_yield_pct,
    dividendYearsPaid5y: row.dividend_years_paid_5y,
