parameters.query:
SELECT row_to_json(t) AS technicals FROM (
  SELECT s.symbol, ta.* FROM technical_analysis ta
  JOIN stocks s ON s.id = ta.stock_id
  WHERE s.symbol = $1 AND s.exchange = $2
  ORDER BY ta.trading_date DESC LIMIT 1
) t;

