const secret = $env.REPORT_WEBHOOK_SECRET;
const headers = $json.headers || {};
const authHeader = headers.authorization || headers.Authorization || '';
let authorized = true;
if (secret && secret.length > 0) {
  authorized = authHeader === ('Bearer ' + secret);
}
return [{ json: { ...$json, authorized } }];

const body = $json.body || {};
const code = String(body.code || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const name = String(body.name || '').trim();
const currency = String(body.currency || '').toUpperCase().trim();
const timezone = String(body.timezone || '').trim();
const eodhdExchangeCode = String(body.eodhdExchangeCode || body.eodhd_exchange_code || '').trim();
const indexCode = (body.indexCode || body.index_code || '').toString().trim() || null;
const minAvgTradedValue = Number(body.minAvgTradedValue ?? body.min_avg_traded_value ?? 0) || 0;
const minAvgVolume = Number(body.minAvgVolume ?? body.min_avg_volume ?? 0) || 0;
const minActiveDays20 = Number(body.minActiveDays20 ?? body.min_active_days_20 ?? 15) || 15;

const errors = [];
if (!code || code.length > 16) errors.push('code is required (max 16 alphanumeric characters)');
if (!name) errors.push('name is required');
if (!currency) errors.push('currency is required (e.g. USD)');
if (!timezone) errors.push('timezone is required (IANA name, e.g. America/New_York)');
if (!eodhdExchangeCode) errors.push('eodhdExchangeCode is required (the provider exchange-code suffix, e.g. US)');

return [{ json: {
  code, name, currency, timezone, eodhdExchangeCode, indexCode,
  minAvgTradedValue, minAvgVolume, minActiveDays20,
  valid: errors.length === 0, errors,
} }];

const row = $input.first() ? $input.first().json : null;
const inserted = !!row;
let code = inserted ? row.code : null;
if (!code) {
  try { code = $('Validate: markets-add').first().json.code; } catch (e) { code = null; }
}
return [{ json: {
  success: true,
  inserted,
  code,
  message: inserted
    ? 'Market added. It runs via manual/Execute-Workflow trigger; enabling its automatic daily schedule is a follow-up n8n step.'
    : 'A market with this code already exists — no changes made.',
} }];

